


WITH grouped AS (
  SELECT
    recid,
    map_agg(field_index || '_' || CAST(m_index AS VARCHAR), field_value) AS f,
    multimap_agg(
      field_index || '_' || CAST(m_index AS VARCHAR),
      CAST(ROW(s_index, field_value) AS ROW(s INTEGER, val VARCHAR))
    ) AS g,
    multimap_agg(
      field_index,
      CAST(ROW(m_index, s_index, field_value) AS ROW(m INTEGER, s INTEGER, val VARCHAR))
    ) AS h,
    max(xml_hash) AS xml_hash
  FROM "iceberg"."staging"."account_attributes"
  GROUP BY recid
)
,
changed AS (
  SELECT DISTINCT g.recid
  FROM grouped g
  LEFT JOIN (SELECT DISTINCT recid, xml_hash FROM "iceberg"."bronze"."account_wide") t
    ON t.recid = g.recid
  WHERE t.recid IS NULL OR t.xml_hash IS DISTINCT FROM g.xml_hash
)
SELECT
  recid,
  recid AS "account_number",
  element_at(CASE WHEN element_at(h, 'c1') IS NULL THEN NULL ELSE transform(sequence(1, array_max(transform(element_at(h, 'c1'), x -> x.m))), i -> element_at(transform(filter(element_at(h, 'c1'), x -> x.m = i), x -> x.val), 1)) END, 1) AS "customer",
  element_at(CASE WHEN element_at(h, 'c10') IS NULL THEN NULL ELSE transform(sequence(1, array_max(transform(element_at(h, 'c10'), x -> x.m))), i -> element_at(transform(filter(element_at(h, 'c10'), x -> x.m = i), x -> x.val), 1)) END, 1) AS "limit_ref",
